targets.expr:
(
  sum(
    tspupirouter_HIT_COUNT_value{
      switchV2API=~"NpciHttpClient.sendPostRequest.*",
      current_cluster!="c1",
      client_host_ip!~".*dc.*"
    }
  ) by (client_host_ip)
  /
  ignoring(client_host_ip) group_left()
  sum(
    tspupirouter_HIT_COUNT_value{
      switchV2API=~"NpciHttpClient.sendPostRequest.*",
      current_cluster!="c1",
      client_host_ip!~".*dc.*"
    }
  )
) * 100

avg(
  tspupirouter_metric_for_txn_turnaround_time_95_percentile{
    type="PAY",
    status="SUCCESS",
    payer_psp=~"paytm|ptyes"
  }
) by (payer_psp, payee_bank, payer_bank)
